 def mask(index):
  meta=next(m for m in manifest['masks']if m['index']==index);a=np.array(Image.open(pin(B/'baseline/masks'/meta['png'])))>0;x,y=meta['box_top_left'];full=np.zeros(shape,bool);full[y:y+a.shape[0],x:x+a.shape[1]]=a;return full,meta
